    priority_queue&lt;long long&gt; pq;
    vector&lt;long long&gt; v(n + 1), b(n + 1);
    long long ans = 0;
    for (int i = 1; i &lt;= n; ++i) {
        long long a;
        cin &gt;&gt; a;
        long long x = a - i;
        pq.push(x);
        pq.push(x);
        ans += pq.top() - x;
        pq.pop();
        v[i] = pq.top(); // Record optimal prefix breakpoint AFTER pop!
    }
    b[n] = v[n];
    for (int i = n - 1; i &gt;= 1; --i) {
        b[i] = min(b[i + 1], v[i]);
    }
    cout &lt;&lt; ans &lt;&lt; "\n";
    for (int i = 1; i &lt;= n; ++i) {
        cout &lt;&lt; (b[i] + i) &lt;&lt; (i == n ? '\n' : ' ');
