                pq.pop();
                total += t.key + v;
                cnt += t.dcnt;
                pq.push({-v, 0});
            }
        }
        return {total, cnt};
    };

    long long lo = 0, hi = 2000000005LL, ans_lam = hi;
    while (lo &lt;= hi) {
