        pts[i] = {x + y, x};
    }
    sort(pts.begin(), pts.end());

    priority_queue&lt;long long&gt; pqL; // Max-heap for left breakpoints
    priority_queue&lt;long long, vector&lt;long long&gt;, greater&lt;long long&gt;&gt; pqR; // Min-heap for right breakpoints
    pqL.push(0);
    pqR.push(0);
    long long shiftR = 0, prev_s = 0, ans = 0;

    for (auto [s, x] : pts) {
        shiftR += (s - prev_s);
        prev_s = s;
        long long L_max = pqL.top();
        long long R_min = pqR.top() + shiftR;
        if (x &lt; L_max) {
            ans += L_max - x;
            pqL.pop();
            pqL.push(x);
            pqL.push(x);
            pqR.push(L_max - shiftR);
        } else if (x &gt; R_min) {
            ans += x - R_min;
            pqR.pop();
            pqR.push(x - shiftR);
            pqR.push(x - shiftR);
            pqL.push(R_min);
        } else {
            pqL.push(x);
            pqR.push(x - shiftR);
        }
    }
