Canonical Slot: Ch 23 — Mastery 1 (Mas-1) | Wave Provenance: 4B-P22
Judge URL: https://www.luogu.com.cn/problem/P5470 (also LOJ #3158 / UOJ #479)
Constraints: \(T \le 10\) test cases, \(\sum N \le 10^6\), \(N \le 2 \times 10^5\), \(1 \le L \le K \le N\), \(1 \le a_i, b_i \le 10^9\).


4-Step Compilation Summary
Having derived the 4-state vertex automaton (State 0: (0,0), State 1: (1,0), State 2: (0,1), State 3: (1,1)) and the 5 elementary residual augmenting walks in Section 23.4, let us highlight two implementation details that make the code ultra-clean:

Initial Greedy Phase (Optional or Unified): You can either run all \(K\) steps directly using the 5-heap automaton starting from free_rem = K - L, OR first greedily pick the top \(K - L\) elements of \(A\) and top \(K - L\) elements of \(B\) and run \(L\) steps. Running all \(K\) steps from \(0\) with free_rem = K - L is completely uniform and avoids any special-case initialization!
Same-Index Guard in Walk 2 (i == j): If Walk 2 (\(\max(H_{A0}) + \max(H_{B0})\)) wins and happens to pick the same index \(i = j\), then \(i\) transitions directly 0 -&gt; 3 and consumes \(0\) free tokens (equivalent to Walk 1)!







Note3-Tier Progressive Hints (#183 — [NOI2019] 序列)






Hint 1: Represent the constraint \(|I \cap J| \ge L\) by a central bottleneck edge \(P \to Q\) of capacity free_rem = K - L that carries all unaligned pairs.
Hint 2: Track state[i] in {0, 1, 2, 3} (bitmask of whether \(i \in I\) and \(i \in J\)) and maintain 5 max-heaps: H_AB (state 0, key \(a_i+b_i\)), H_A0 (state 0, key \(a_i\)), H_B0 (state 0, key \(b_i\)), H_B1 (state 1, key \(b_i\)), and H_A2 (state 2, key \(a_i\)).
Hint 3: At each of the \(K\) steps, evaluate the 5 candidate walks (Walk 2 only if free_rem &gt; 0). Remember that Walk 5 (H_A2.top() + H_B1.top()) turns two half-selected nodes into two aligned (1, 1) nodes and increments free_rem++!










TipComplete C++ Solution ([NOI2019 / Luogu P5470] 序列)





// [NOI2019 / Luogu P5470] 序列 (Sequence) — 5-Heap Residual State Automaton
// Time: O(N log N), Space: O(N)
#include &lt;bits/stdc++.h&gt;
using namespace std;

const long long NEG_INF = -1e18;

struct Entry {
    long long val;
    int id;
    bool operator&lt;(const Entry& o) const { return val &lt; o.val; }
};

void solve_testcase() {
    int n, k, l;
    cin &gt;&gt; n &gt;&gt; k &gt;&gt; l;
    vector&lt;long long&gt; a(n + 1), b(n + 1);
    for (int i = 1; i &lt;= n; ++i) cin &gt;&gt; a[i];
    for (int i = 1; i &lt;= n; ++i) cin &gt;&gt; b[i];

    // State bitmask: 0 = (0,0), 1 = A-only (1,0), 2 = B-only (0,1), 3 = Both (1,1)
    vector&lt;int&gt; state(n + 1, 0);
    priority_queue&lt;Entry&gt; hAB, hA0, hB0, hB1, hA2;

    for (int i = 1; i &lt;= n; ++i) {
        hAB.push({a[i] + b[i], i});
        hA0.push({a[i], i});
        hB0.push({b[i], i});
    }

    auto clean = [&]() {
        while (!hAB.empty() && state[hAB.top().id] != 0) hAB.pop();
        while (!hA0.empty() && state[hA0.top().id] != 0) hA0.pop();
        while (!hB0.empty() && state[hB0.top().id] != 0) hB0.pop();
        while (!hB1.empty() && state[hB1.top().id] != 1) hB1.pop();
        while (!hA2.empty() && state[hA2.top().id] != 2) hA2.pop();
    };

    auto set_state = [&](int u, int new_st) {
        state[u] = new_st;
        if (new_st == 1) hB1.push({b[u], u});
        else if (new_st == 2) hA2.push({a[u], u});
    };

    int free_rem = k - l;
    long long total_sum = 0;

    for (int step = 0; step &lt; k; ++step) {
        clean();
        long long w1 = hAB.empty() ? NEG_INF : hAB.top().val;
        long long w2 = (free_rem &gt; 0 && !hA0.empty() && !hB0.empty())
                       ? (hA0.top().val + hB0.top().val) : NEG_INF;
        long long w3 = (!hB1.empty() && !hA0.empty())
                       ? (hB1.top().val + hA0.top().val) : NEG_INF;
        long long w4 = (!hA2.empty() && !hB0.empty())
                       ? (hA2.top().val + hB0.top().val) : NEG_INF;
        long long w5 = (!hA2.empty() && !hB1.empty())
                       ? (hA2.top().val + hB1.top().val) : NEG_INF;

        long long best = max({w1, w2, w3, w4, w5});
        total_sum += best;

        if (best == w1) {
            int u = hAB.top().id;
            set_state(u, 3);
        } else if (best == w2) {
            int u = hA0.top().id;
            int v = hB0.top().id;
            if (u == v) {
                set_state(u, 3); // Degenerates to Walk 1 (0 free tokens used)
            } else {
                set_state(u, 1);
                set_state(v, 2);
                free_rem--;
            }
        } else if (best == w3) {
            int j = hB1.top().id;
            int i = hA0.top().id;
            set_state(j, 3);
            set_state(i, 1);
        } else if (best == w4) {
            int i = hA2.top().id;
            int j = hB0.top().id;
            set_state(i, 3);
            set_state(j, 2);
        } else {
            // Walk 5: Cross-swap completion REFUNDS +1 free token!
            int i = hA2.top().id;
            int j = hB1.top().id;
            set_state(i, 3);
            set_state(j, 3);
            free_rem++;
        }
    }
    cout &lt;&lt; total_sum &lt;&lt; "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    if (cin &gt;&gt; T) while (T--) solve_testcase();
    return 0;
}







