// Method: Coordinate Doubling x -&gt; (2x, 2x+1) + Equation Differencing + DAG DP Potentials + Dijkstra MCMF
#include &lt;bits/stdc++.h&gt;
using namespace std;

const long long INF = 1e18;

struct Edge {
    int to, rev, cap;
    long long cost;
