    add_edge(S, 1, K, 0);
    add_edge(W + 1, T, K, 0);
    for (int i = 1; i &lt;= W; ++i) {
        add_edge(i, i + 1, K, 0);
    }

    vector&lt;vector&lt;pair&lt;int, long long&gt;&gt;&gt; dag_edges(W + 2);
    for (int j = 1; j &lt;= n; ++j) {
        int l = max(1, j - m + 1);
        int r = min(W, j);
        add_edge(l, r + 1, 1, -c[j]);
        dag_edges[l].push_back({r + 1, -c[j]});
    }

    vector&lt;long long&gt; pi(V, INF);
    pi[S] = pi[1] = 0;
    for (int u = 1; u &lt;= W + 1; ++u) {
        if (u &lt;= W) pi[u + 1] = min(pi[u + 1], pi[u]);
        for (auto [v, cost] : dag_edges[u]) {
