TipFull C++ Solution for #117 (Luogu P2046 — [NOI2010] Altitude)





#include &lt;bits/stdc++.h&gt;
using namespace std;

const long long INF = 1e18;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin &gt;&gt; N)) return 0;

    int S = 0, T = N * N + 1;
    auto face = [&](int r, int c) -&gt; int {
        if (r == N + 1 || c == 0) return S; // Bottom-Left outer boundary
        if (r == 0 || c == N + 1) return T; // Top-Right outer boundary
        return (r - 1) * N + c;
    };

    vector&lt;vector&lt;pair&lt;int, int&gt;&gt;&gt; adj(T + 1);
    auto add_arc = [&](int u, int v, int w) {
