// Uses ConvexMCMF from Section 5.1
void solve_haoi2010_order() {
    const long long INF = 1e15;
    int n;
    long long m_fee, S_cap;
    if (!(cin &gt;&gt; n &gt;&gt; m_fee &gt;&gt; S_cap)) return;

    vector&lt;long long&gt; U(n + 1), d(n + 1);
    for (int i = 1; i &lt;= n; ++i) cin &gt;&gt; U[i];
    for (int i = 1; i &lt;= n; ++i) cin &gt;&gt; d[i];

    int S = 0, T = n + 1;
    ConvexMCMF mcmf(T + 1);

    for (int i = 1; i &lt;= n; ++i) {
        mcmf.add_edge(S, i, INF, d[i]);
        mcmf.add_edge(i, T, U[i], 0);
        if (i &lt; n) mcmf.add_edge(i, i + 1, S_cap, m_fee);
    }

    cout &lt;&lt; mcmf.solve(S, T).second &lt;&lt; "\n";
}









