// Uses ConvexMCMF from Section 5.1
void solve_sdoi2011_work() {
    const long long INF = 1e15;
    int M, N;
    if (!(cin &gt;&gt; M &gt;&gt; N)) return;

    int S = 0, T = M + N + 1;
    ConvexMCMF mcmf(T + 1);

    for (int j = 1; j &lt;= N; ++j) {
