            int can_make;
            cin &gt;&gt; can_make;
            if (can_make) mcmf.add_edge(i, M + j, INF, 0);
        }
    }

    for (int i = 1; i &lt;= M; ++i) {
        int K;
        cin &gt;&gt; K;
        vector&lt;long long&gt; thresh(K + 2, 0), slope(K + 1, 0);
