Problem #185 (S1 — Stepping Stone 1): [SCOI2012 / Luogu P5038] Strange Game (奇怪的游戏)

Judge URL: https://www.luogu.com.cn/problem/P5038
Constraints: \(T \le 10\) testcases, \(N, M \le 40\), initial cell values \(0 \le a_{r,c} \le 10^9\). Time Limit: \(1.0\text{ s}\).
Cross-Archive Benchmark Note (LOJ #101 / Luogu P4722 High-Speed Max-Flow): When testing feasibility \(O(\log U)\) times on \(V = NM \le 1600\) vertices with capacities up to \(10^{12}\), standard Dinic with current-arc and dead-node pruning (FM-03) runs in \(&lt; 50\text{ ms}\); on dense adversarial graphs (Luogu P4722), Highest-Label Preflow-Push (HLPP, \(O(V^2\sqrt{E})\)) provides an worst-case safety net.


4-Step Compilation Scratchpad

Step 1 (Diagnostic Signal): Operations increment pairs of adjacent cells on an \(N \times M\) grid. The grid is bipartite (\(B \sqcup W\) by \((r+c) \bmod 2\)), and every operation adds \(+1\) to one black cell and \(+1\) to one white cell.
Step 2 (Algebraic Invariant): Let \(c_B, s_B\) and \(c_W, s_W\) be the counts and initial sums of black and white cells. Reaching final value \(X\) requires \((c_B - c_W) X = s_B - s_W\).

If \(NM\) is odd (\(c_B - c_W = 1\)): \(X = s_B - s_W\) is uniquely determined. Check \(X \ge \max a_{r,c}\) and run Dinic once.
If \(NM\) is even (\(c_B = c_W\)): require \(s_B = s_W\); since an even grid has a perfect domino tiling, feasibility of \(X\) implies feasibility of \(X+1\). Binary search \(X \in [\max a_{r,c}, 2 \cdot 10^{11}]\).

Step 3 (Graph Compilation): For a given \(X\), add \(S \to u\) (cap \(= X - a_u\)) for \(u \in B\), \(u \to v\) (cap \(= \infty\)) for adjacent \(u \in B, v \in W\), and \(v \to T\) (cap \(= X - a_v\)) for \(v \in W\). Check if \(\text{MaxFlow} = c_B X - s_B\).
Step 4 (Toy Trace & Broken-Gadget Audit): On a \(1 \times 3\) grid \([1, 2, 1]\), \(c_B = 2, s_B = 2\) and \(c_W = 1, s_W = 2\). Then \(X = s_B - s_W = 0 &lt; \max a_{r,c} = 2\), immediately outputting -1 without a single flow call! Binary searching \(X\) here (FM-24) would test \(X \ge 2\) where \(c_B X - s_B \ne c_W X - s_W\) and produce WA.







Note3-Tier Progressive Hints for #185 ([SCOI2012] 奇怪的游戏)






Tier 1 (Invariant Discovery): Color the grid like a chessboard. How much does \(S_B - S_W\) (the difference between the sum of black cells and the sum of white cells) change after one operation?
Tier 2 (Parity Split): Since \(S_B - S_W\) is invariant, at the end of the game when every cell equals \(X\), we must have \(c_B X - c_W X = s_B - s_W\). Separate into \(NM \equiv 1 \pmod 2\) (\(c_B = c_W + 1\)) vs. \(NM \equiv 0 \pmod 2\) (\(c_B = c_W\)).
Tier 3 (Binary Search Bound & Flow Check): When \(NM\) is even and \(s_B = s_W\), binary search \(X \in [\max a_{r,c}, \max a_{r,c} + 10^{11}]\). Use long long for all capacities and flow accumulators!










TipComplete C++17 Solution for #185 ([SCOI2012] 奇怪的游戏)





#include &lt;bits/stdc++.h&gt;
using namespace std;

const long long INF = 1e16;

struct Dinic {
    struct Edge { int to, rev; long long cap; };
    int n, s, t;
    vector&lt;vector&lt;Edge&gt;&gt; adj;
    vector&lt;int&gt; level, ptr;

    Dinic(int n, int s, int t) : n(n), s(s), t(t), adj(n), level(n), ptr(n) {}

    void add_edge(int from, int to, long long cap) {
        adj[from].push_back({to, (int)adj[to].size(), cap});
        adj[to].push_back({from, (int)adj[from].size() - 1, 0});
    }

    bool bfs() {
        fill(level.begin(), level.end(), -1);
        level[s] = 0;
        queue&lt;int&gt; q;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (auto& edge : adj[v]) {
                if (edge.cap &gt; 0 && level[edge.to] == -1) {
                    level[edge.to] = level[v] + 1;
                    q.push(edge.to);
                }
            }
        }
        return level[t] != -1;
    }

    long long dfs(int v, long long pushed) {
        if (pushed == 0 || v == t) return pushed;
        for (int& cid = ptr[v]; cid &lt; (int)adj[v].size(); ++cid) {
            auto& edge = adj[v][cid];
            int tr = edge.to;
            if (level[v] + 1 != level[tr] || edge.cap == 0) continue;
            long long tr_pushed = dfs(tr, min(pushed, edge.cap));
            if (tr_pushed == 0) continue;
            edge.cap -= tr_pushed;
            adj[tr][edge.rev].cap += tr_pushed;
            return tr_pushed;
        }
        level[v] = -1; // FM-03: Dead-node pruning
        return 0;
    }

    long long max_flow() {
        long long flow = 0;
        while (bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while (long long pushed = dfs(s, INF)) flow += pushed;
        }
        return flow;
    }
};

void solve() {
    int n, m;
    if (!(cin &gt;&gt; n &gt;&gt; m)) return;
    vector&lt;vector&lt;long long&gt;&gt; a(n, vector&lt;long long&gt;(m));
    long long cB = 0, cW = 0, sB = 0, sW = 0, mx = 0;
    for (int r = 0; r &lt; n; ++r) {
        for (int c = 0; c &lt; m; ++c) {
            cin &gt;&gt; a[r][c];
            mx = max(mx, a[r][c]);
            if ((r + c) % 2 == 0) { cB++; sB += a[r][c]; }
            else { cW++; sW += a[r][c]; }
        }
    }

    auto check = [&](long long X) -&gt; bool {
        if (X &lt; mx) return false;
        int S = n * m, T = n * m + 1;
        Dinic dinic(n * m + 2, S, T);
        long long need = 0;
        int dr[4] = {-1, 1, 0, 0}, dc[4] = {0, 0, -1, 1};
        for (int r = 0; r &lt; n; ++r) {
            for (int c = 0; c &lt; m; ++c) {
                int u = r * m + c;
                if ((r + c) % 2 == 0) {
                    dinic.add_edge(S, u, X - a[r][c]);
                    need += X - a[r][c];
                    for (int d = 0; d &lt; 4; ++d) {
                        int nr = r + dr[d], nc = c + dc[d];
                        if (nr &gt;= 0 && nr &lt; n && nc &gt;= 0 && nc &lt; m)
                            dinic.add_edge(u, nr * m + nc, INF);
                    }
                } else {
                    dinic.add_edge(u, T, X - a[r][c]);
                }
            }
        }
        return dinic.max_flow() == need;
    };

    if (cB != cW) {
        long long X = (sB - sW) / (cB - cW);
        if (check(X)) cout &lt;&lt; (cB * X - sB) &lt;&lt; "\n";
        else cout &lt;&lt; -1 &lt;&lt; "\n";
    } else {
        if (sB != sW) { cout &lt;&lt; -1 &lt;&lt; "\n"; return; }
        long long lo = mx, hi = 200000000000LL, ans = -1;
        while (lo &lt;= hi) {
            long long mid = lo + (hi - lo) / 2;
            if (check(mid)) { ans = mid; hi = mid - 1; }
            else lo = mid + 1;
        }
        if (ans == -1) cout &lt;&lt; -1 &lt;&lt; "\n";
        else cout &lt;&lt; (cB * ans - sB) &lt;&lt; "\n";
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    if (cin &gt;&gt; T) while (T--) solve();
    return 0;
}







Problem #186 (S2 — Stepping Stone 2): [BOI 2004 / Luogu P4331] Sequence (数字序列) & [BJWC2018 / LOJ #2028] Napkin Plan (餐巾计划问题)

Judge URLs: https://www.luogu.com.cn/problem/P4331 (1D \(L_1\) Isotonic Regression) | https://loj.ac/p/2028 (Simulated MCMF / Ternary Search on Time-Deferred Stock)
Constraints (Luogu P4331): \(N \le 10^6\), \(0 \le a_i \le 2 \cdot 10^9\). Find strictly increasing integers \(z_1 &lt; z_2 &lt; \dots &lt; z_N\) minimizing \(\sum_{i=1}^N |z_i - a_i|\) and output both the minimum cost and the sequence \(z_i\). Time Limit: \(1.0\text{ s}\).


4-Step Compilation Scratchpad (Luogu P4331 — From 整体二分 Closure to \(O(N \log N)\) Slope Trick / Leftist Heap)

Step 1 (Diagnostic Signal): We want \(z_1 &lt; z_2 &lt; \dots &lt; z_N\) in \(\mathbb{Z}\) minimizing \(\sum |z_i - a_i|\) with \(N = 10^6\). This is 1D \(L_1\) Isotonic Regression (AL-05), but \(N = 10^6\) triggers Stage 1’s Direction B Flow Elimination (AL-16)!
Step 2 (Algebraic Transformation): Substitute \(x_i = z_i - i\) and \(b_i = a_i - i\). Then \(z_1 &lt; z_2 &lt; \dots &lt; z_N\) (in integers) becomes the standard non-decreasing chain poset:
\[
\min_{x_1 \le x_2 \le \dots \le x_N} \sum_{i=1}^N |x_i - b_i|
\]
Step 3 (Connecting 整体二分 Min-Cut to Pool-Adjacent-Violators / Slope Trick): In our 整体二分 closure network for a chain \(1 \to 2 \to \dots \to N\), an upper closure is simply a suffix \([k, N]\), and whenever \(b_i &gt; b_{i+1}\), the poset arc \(i \to i+1\) is tight (\(x_i^* = x_{i+1}^*\)) in the optimal cut! Merging adjacent violating blocks \(B_1, B_2\) with \(\text{median}(B_1) &gt; \text{median}(B_2)\) and replacing their objective \(\sum_{i \in B} |x - b_i|\) by its median (via mergeable max-heaps of size \(\lceil |B|/2 \rceil\), or Slope Trick priority queue) solves the 1D poset in \(O(N \log N)\) time and reconstructs \(x_i^*\) exactly!
Step 4 (Toy Trace): Suppose \(a = [5, 4, 3]\), so \(b_i = a_i - i = [4, 2, 0]\).

Block 1: \(\{4\}\), median \(4\).
Block 2: \(\{2\}\), since \(4 &gt; 2\), merge \(\{4, 2\}\) (size 2, keep lower median \(2\)).
Block 3: \(\{0\}\), since \(2 &gt; 0\), merge \(\{4, 2, 0\}\) (size 3, median \(2\)).
Optimal \(x^* = [2, 2, 2] \implies z_i^* = x_i^* + i = [3, 4, 5]\), cost \(|3-5| + |4-4| + |5-3| = 4\).








Note3-Tier Progressive Hints for #186 ([BOI 2004] Sequence & [BJWC2018] 餐巾计划)






Tier 1 (Strict to Weak Inequality): Replace \(z_i &lt; z_{i+1}\) with \(z_i - i \le z_{i+1} - (i+1)\) by setting \(b_i = a_i - i\) and \(x_i = z_i - i\).
Tier 2 (Pool-Adjacent-Violators Lemma): When \(b_u &gt; b_{u+1}\), Theorem 24.1 guarantees that the poset edge \(u \to u+1\) is active, so \(x_u^* = x_{u+1}^*\). Thus the two elements fuse into a single contiguous block whose optimal value is the median of the block!
Tier 3 (Mergeable Max-Heap Reconstruction): Maintain a stack of blocks. Each block stores a leftist heap (or std::priority_queue with small-to-large merge) containing the smallest \(\lceil \text{len}/2 \rceil\) elements of that block; its top is the block’s median. Whenever the previous block’s median exceeds the current block’s median, merge them and pop until heap size equals \(\lceil (\text{len}_1 + \text{len}_2)/2 \rceil\). (For [BJWC2018] 餐巾计划问题 with \(N = 2 \cdot 10^5\), the total cost is convex in the total number of purchased new napkins \(K\); ternary search \(K\) and greedily use free carry-over, then slow-wash from oldest days, then fast-wash from newest days via a deque in \(O(N \log U)\)!).










TipComplete C++17 Solution for #186 ([BOI 2004 / Luogu P4331] Sequence)





#include &lt;bits/stdc++.h&gt;
using namespace std;

struct LeftistNode {
    long long val;
    int l = 0, r = 0, dist = 0;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin &gt;&gt; n)) return 0;
    vector&lt;long long&gt; b(n + 1);
    vector&lt;LeftistNode&gt; pool(n + 1);
    for (int i = 1; i &lt;= n; ++i) {
        long long a;
        cin &gt;&gt; a;
        b[i] = a - i;
        pool[i] = {b[i], 0, 0, 0};
    }

    auto merge = [&](auto& self, int x, int y) -&gt; int {
        if (!x || !y) return x | y;
        if (pool[x].val &lt; pool[y].val) swap(x, y); // Max-heap root is median
        pool[x].r = self(self, pool[x].r, y);
        if (pool[pool[x].l].dist &lt; pool[pool[x].r].dist)
            swap(pool[x].l, pool[x].r);
        pool[x].dist = pool[pool[x].r].dist + 1;
        return x;
    };

    struct Block { int root, l, r, sz; };
    vector&lt;Block&gt; st;
    for (int i = 1; i &lt;= n; ++i) {
        Block cur = {i, i, i, 1};
        while (!st.empty() && pool[st.back().root].val &gt; pool[cur.root].val) {
            Block prev = st.back();
            st.pop_back();
            cur.root = merge(merge, prev.root, cur.root);
            cur.l = prev.l;
            cur.sz += prev.sz;
            int target_sz = (cur.r - cur.l + 2) / 2;
            while (cur.sz &gt; target_sz) {
                cur.root = merge(merge, pool[cur.root].l, pool[cur.root].r);
                cur.sz--;
            }
        }
        st.push_back(cur);
    }

    vector&lt;long long&gt; x(n + 1);
    long long ans = 0;
    for (auto& blk : st) {
        long long med = pool[blk.root].val;
        for (int i = blk.l; i &lt;= blk.r; ++i) {
            x[i] = med;
            ans += llabs(x[i] - b[i]);
        }
    }
    cout &lt;&lt; ans &lt;&lt; "\n";
    for (int i = 1; i &lt;= n; ++i)
        cout &lt;&lt; (x[i] + i) &lt;&lt; (i == n ? '\n' : ' ');
    return 0;
}







Problem #187 (I1 — Intermediate 1): [SHOI2004 / Luogu P4412 / BZOJ 1937] Inverse Minimum Spanning Tree (最小生成树) & [CF 1307G] Cow and Exercise

Judge URLs: https://www.luogu.com.cn/problem/P4412 (Inverse MST via \(L_1\) Isotonic Regression / LP Dual) | https://codeforces.com/problemset/problem/1307/G (Parametric Shortest-Path Interdiction LP Dual via SSP MCMF Hull)
Constraints (Luogu P4412): \(N \le 50\) vertices, \(M \le 1000\) undirected edges with initial weights \(w_e\) and unit modification costs \(c_e\) (or \(c_e = 1\)). Given a specific spanning tree \(T_0\), modify edge weights to \(x_e\) minimizing \(\sum_{e} c_e |x_e - w_e|\) so that \(T_0\) is a minimum spanning tree.


4-Step Compilation Scratchpad (Luogu P4412 & CF 1307G)

Step 1 (Diagnostic Signal): We want to modify edge weights \(w_e \to x_e\) under the \(L_1\) norm so that a fixed spanning tree \(T_0\) satisfies Kruskal’s MST optimality condition (AL-05 + AL-14).
Step 2 (Algebraic Poset / LP Dual Formulation):

Perspective A (\(L_1\) Isotonic Regression Poset, Ch 24.1): A spanning tree \(T_0\) is an MST under weights \(x\) if and only if for every non-tree edge \(f = (u, v) \notin T_0\) and every tree edge \(e \in P_{T_0}(u, v)\) on the unique path between \(u\) and \(v\) in \(T_0\), we have:
\[
x_e \le x_f \qquad \forall f \notin T_0, \; \forall e \in P_{T_0}(f)
\]
Notice this is a bipartite poset between the \(N-1\) tree edges \(e \in T_0\) (which only ever decrease, \(x_e \le w_e\)) and the \(M - N + 1\) non-tree edges \(f \notin T_0\) (which only ever increase, \(x_f \ge w_f\)).
Perspective B (LP Dual \(\to\) Bipartite Matching / MCMF, Ch 19–Ch 20): Writing \(x_e = w_e - d_e\) (\(d_e \ge 0\)) for \(e \in T_0\) and \(x_f = w_f + d_f\) (\(d_f \ge 0\)) for \(f \notin T_0\), the constraint \(x_e \le x_f\) becomes:
\[
d_e + d_f \ge \max(0, w_e - w_f) \qquad \forall f \notin T_0, \; e \in P_{T_0}(f)
\]
Minimizing \(\sum_{e \in T_0} c_e d_e + \sum_{f \notin T_0} c_f d_f\) subject to \(d_e + d_f \ge \text{gap}(e, f)\) is the Dual of Maximum-Weight Bipartite \(b\)-Matching (or Min-Cost Flow) between \(T_0\) and \(E \setminus T_0\)! And by Theorem 24.1, running 整体二分 on the bipartite poset \((T_0 \to E \setminus T_0)\) finds the exact modified weights \(x_e^*\) in \(O(\text{Dinic}(M, NM) \log U)\) time!
Perspective C (CF 1307G Cow and Exercise — Inverse Shortest Path Dual): Increasing edge weights on a directed graph within budget \(X\) to maximize the \(1\)-to-\(N\) shortest path \(\lambda\) is the dual of parametric MCMF: run SSP from \(1\) to \(N\), record each augmenting path’s cumulative flow \(k\) and cumulative cost \(C_k\), and answer each query \(X\) in \(O(\#\text{paths})\) via the lower envelope \(\min_{k \ge 1} (C_k + X) / k\)!








Note3-Tier Progressive Hints for #187 ([SHOI2004] 最小生成树 & [CF 1307G] Cow and Exercise)






Tier 1 (Cycle Optimality Condition): For \(T_0\) to be an MST, add each non-tree edge \(f = (u, v) \notin T_0\) one by one. Which tree edges \(e \in T_0\) can swap with \(f\)?
Tier 2 (Poset Edges): Every \(e \in P_{T_0}(u, v)\) must satisfy \(x_e \le x_f\). Add directed poset edges \(e \to f\) for all \(e \in P_{T_0}(u, v)\).
Tier 3 (整体二分 + Max-Weight Closure): Use solve(V_cur, E_cur, L, R) from Section 1.3 with \(\Delta_i(M) = c_i |M - w_i| - c_i |M + 1 - w_i|\) (+c_i if \(M &lt; w_i\), and -c_i if \(M \ge w_i\)).










TipComplete C++17 Solution for #187 ([SHOI2004 / Luogu P4412] 最小生成树 + [CF 1307G] Cow and Exercise)





// Part A: [SHOI2004 / Luogu P4412] Inverse MST via Parallel D&C Isotonic Regression
#include &lt;bits/stdc++.h&gt;
using namespace std;

const long long INF = 1e15;

struct Dinic {
    struct Edge { int to, rev; long long cap; };
    int n, s, t;
    vector&lt;vector&lt;Edge&gt;&gt; adj;
    vector&lt;int&gt; level, ptr;
    Dinic(int n, int s, int t) : n(n), s(s), t(t), adj(n), level(n), ptr(n) {}
    void add_edge(int u, int v, long long cap) {
        adj[u].push_back({v, (int)adj[v].size(), cap});
        adj[v].push_back({u, (int)adj[u].size() - 1, 0});
    }
    bool bfs() {
        fill(level.begin(), level.end(), -1);
        level[s] = 0;
        queue&lt;int&gt; q; q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& e : adj[u])
                if (e.cap &gt; 0 && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
        }
        return level[t] != -1;
    }
    long long dfs(int u, long long pushed) {
        if (!pushed || u == t) return pushed;
        for (int& cid = ptr[u]; cid &lt; (int)adj[u].size(); ++cid) {
            auto& e = adj[u][cid];
            if (level[u] + 1 != level[e.to] || e.cap == 0) continue;
            long long tr = dfs(e.to, min(pushed, e.cap));
            if (!tr) continue;
            e.cap -= tr; adj[e.to][e.rev].cap += tr;
            return tr;
        }
        level[u] = -1;
        return 0;
    }
    long long max_flow() {
        long long f = 0;
        while (bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while (long long p = dfs(s, INF)) f += p;
        }
        return f;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if (!(cin &gt;&gt; n &gt;&gt; m)) return 0;
    struct RawEdge { int u, v; long long w, c; int in_tree; };
    vector&lt;RawEdge&gt; edges(m);
    for (int i = 0; i &lt; m; ++i) {
        // Adapt input format: u, v, w, in_tree, cost c (default 1 if unweighted L1)
        cin &gt;&gt; edges[i].u &gt;&gt; edges[i].v &gt;&gt; edges[i].w &gt;&gt; edges[i].in_tree;
        edges[i].c = 1;
    }
    vector&lt;vector&lt;pair&lt;int, int&gt;&gt;&gt; tree_adj(n + 1);
    for (int i = 0; i &lt; m; ++i) {
        if (edges[i].in_tree) {
            tree_adj[edges[i].u].push_back({edges[i].v, i});
            tree_adj[edges[i].v].push_back({edges[i].u, i});
        }
    }
    vector&lt;pair&lt;int, int&gt;&gt; poset_edges;
    for (int f = 0; f &lt; m; ++f) {
        if (edges[f].in_tree) continue;
        // Find path in T_0 between edges[f].u and edges[f].v
        vector&lt;int&gt; par_e(n + 1, -1), par_v(n + 1, -1);
        queue&lt;int&gt; q; q.push(edges[f].u); par_v[edges[f].u] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto [nxt, eid] : tree_adj[u]) {
                if (par_v[nxt] == -1) {
                    par_v[nxt] = u; par_e[nxt] = eid;
                    q.push(nxt);
                }
            }
        }
        for (int cur = edges[f].v; cur != edges[f].u; cur = par_v[cur])
            poset_edges.push_back({par_e[cur], f}); // x_e &lt;= x_f
    }

    vector&lt;long long&gt; ans(m);
    vector&lt;int&gt; idx(m), local_id(m);
    iota(idx.begin(), idx.end(), 0);

    auto solve_iso = [&](auto& self, vector&lt;int&gt;& V, vector&lt;pair&lt;int, int&gt;&gt;& E, long long L, long long R) -&gt; void {
        if (V.empty()) return;
        if (L == R) {
            for (int u : V) ans[u] = L;
            return;
        }
        long long M = L + (R - L) / 2;
        int k = V.size();
        for (int i = 0; i &lt; k; ++i) local_id[V[i]] = i;
        int S = k, T = k + 1;
        Dinic dinic(k + 2, S, T);
        for (int i = 0; i &lt; k; ++i) {
            int u = V[i];
            long long delta = (M &lt; edges[u].w) ? edges[u].c : -edges[u].c;
            if (delta &gt; 0) dinic.add_edge(S, i, delta);
            else dinic.add_edge(i, T, -delta);
        }
        for (auto [u, v] : E)
            dinic.add_edge(local_id[u], local_id[v], INF);
        dinic.max_flow();
        vector&lt;int&gt; VL, VR;
        for (int i = 0; i &lt; k; ++i) {
            if (dinic.level[i] != -1) VR.push_back(V[i]);
            else VL.push_back(V[i]);
        }
        vector&lt;pair&lt;int, int&gt;&gt; EL, ER;
        for (auto [u, v] : E) {
            bool uR = (dinic.level[local_id[u]] != -1);
            bool vR = (dinic.level[local_id[v]] != -1);
            if (!uR && !vR) EL.push_back({u, v});
            else if (uR && vR) ER.push_back({u, v});
        }
        self(self, VL, EL, L, M);
        self(self, VR, ER, M + 1, R);
    };

    solve_iso(solve_iso, idx, poset_edges, 0, 1000000);
    long long total_cost = 0;
    for (int i = 0; i &lt; m; ++i) total_cost += edges[i].c * llabs(ans[i] - edges[i].w);
    cout &lt;&lt; total_cost &lt;&lt; "\n";
    return 0;
}







