Step 2 (Linear Basis Exchange Poset Extraction):

Insert the \(m\) elements of basis \(A\) into an \(\mathbb{F}_2^{64}\) linear basis while tracking the coordinate mask of which elements of \(A\) XOR-sum to each basis vector. For every \(j \notin A\), decompose \(c_j\) into its unique subset \(S_A(j) \subseteq A\) and add poset constraint \(x_i \le x_j\) (\(i \to j\)) for all \(i \in S_A(j)\).
Repeat for basis \(B\): for every \(j \notin B\), decompose \(c_j\) into \(S_B(j) \subseteq B\) and add poset constraint \(x_j \le x_i\) (\(j \to i\)) for all \(i \in S_B(j)\).

Step 3 (Graph Compilation via 整体二分): Run solve(V_cur, E_cur, L, R) on \([0, 10^6]\) with \(\Delta_i(M) = (M - v_i)^2 - (M + 1 - v_i)^2 = 2(v_i - M) - 1\).
Step 4 (Broken-Gadget Audit FM-24): Ensure the Dinic graph inside solve has size \(|V_{\text{cur}}| + 2\), NOT \(N + 2\)!







Note3-Tier Progressive Hints for #188 ([省选联考 2020 A卷] 魔法商店)






Tier 1 (Basis Optimality via Single-Element Swaps): Why do we only need to compare \(j \notin A\) against the elements \(i \in A\) whose XOR sum equals \(c_j\)? By the Matroid Basis Exchange Theorem, if \(x_i \le x_j\) for all \(i \in S_A(j)\), then \(A\) is globally minimum-weight among all bases!
Tier 2 (Tracking Coordinate Masks in Gaussian Elimination): When inserting the \(k\)-th element of \(A\) (\(0 \le k &lt; m\)) into the 64-bit XOR basis, maintain an auxiliary unsigned long long mask = (1ULL &lt;&lt; k). Whenever you XOR val ^= basis_val[b], also XOR mask ^= basis_mask[b].
Tier 3 (Quadratic Slice Reward): At midpoint \(M = \lfloor (L + R) / 2 \rfloor\), moving \(x_i\) from \(M\) to \(M+1\) changes \((x_i - v_i)^2\) by \((M + 1 - v_i)^2 - (M - v_i)^2 = 2(M - v_i) + 1\). Thus the promotion reward is \(\Delta_i(M) = 2(v_i - M) - 1\).










TipComplete C++17 Solution for #188 ([省选联考 2020 A卷 / Luogu P6621] 魔法商店)





#include &lt;bits/stdc++.h&gt;
using namespace std;

using ull = unsigned long long;
const long long INF = 1e16;

struct Dinic {
    struct Edge { int to, rev; long long cap; };
    int n, s, t;
    vector&lt;vector&lt;Edge&gt;&gt; adj;
    vector&lt;int&gt; level, ptr;
    Dinic(int n, int s, int t) : n(n), s(s), t(t), adj(n), level(n), ptr(n) {}
    void add_edge(int u, int v, long long cap) {
        adj[u].push_back({v, (int)adj[v].size(), cap});
        adj[v].push_back({u, (int)adj[u].size() - 1, 0});
    }
    bool bfs() {
        fill(level.begin(), level.end(), -1);
        level[s] = 0;
        queue&lt;int&gt; q; q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& e : adj[u])
                if (e.cap &gt; 0 && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
        }
        return level[t] != -1;
    }
    long long dfs(int u, long long pushed) {
        if (!pushed || u == t) return pushed;
        for (int& cid = ptr[u]; cid &lt; (int)adj[u].size(); ++cid) {
            auto& e = adj[u][cid];
            if (level[u] + 1 != level[e.to] || e.cap == 0) continue;
            long long tr = dfs(e.to, min(pushed, e.cap));
            if (!tr) continue;
            e.cap -= tr; adj[e.to][e.rev].cap += tr;
            return tr;
        }
        level[u] = -1;
        return 0;
    }
    long long max_flow() {
        long long f = 0;
        while (bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while (long long p = dfs(s, INF)) f += p;
        }
        return f;
    }
};

struct XorBasis {
    ull val[64] = {0}, mask[64] = {0};
    void insert(ull x, int bit_idx) {
        ull m = 1ULL &lt;&lt; bit_idx;
        for (int b = 63; b &gt;= 0; --b) {
            if (!(x &gt;&gt; b & 1)) continue;
            if (!val[b]) { val[b] = x; mask[b] = m; return; }
            x ^= val[b]; m ^= mask[b];
        }
    }
    ull query_mask(ull x) const {
        ull m = 0;
        for (int b = 63; b &gt;= 0; --b) {
            if (x &gt;&gt; b & 1) { x ^= val[b]; m ^= mask[b]; }
        }
        return m;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if (!(cin &gt;&gt; n &gt;&gt; m)) return 0;
    vector&lt;ull&gt; c(n);
    vector&lt;long long&gt; v(n);
    for (int i = 0; i &lt; n; ++i) cin &gt;&gt; c[i];
    for (int i = 0; i &lt; n; ++i) cin &gt;&gt; v[i];

    vector&lt;int&gt; A(m), B(m), inA(n, 0), inB(n, 0);
    XorBasis basisA, basisB;
    for (int i = 0; i &lt; m; ++i) { cin &gt;&gt; A[i]; --A[i]; inA[A[i]] = 1; basisA.insert(c[A[i]], i); }
    for (int i = 0; i &lt; m; ++i) { cin &gt;&gt; B[i]; --B[i]; inB[B[i]] = 1; basisB.insert(c[B[i]], i); }

    vector&lt;pair&lt;int, int&gt;&gt; edges;
    for (int j = 0; j &lt; n; ++j) {
        if (!inA[j]) {
            ull msk = basisA.query_mask(c[j]);
            for (int k = 0; k &lt; m; ++k)
                if (msk &gt;&gt; k & 1) edges.push_back({A[k], j}); // x_{A[k]} &lt;= x_j
        }
        if (!inB[j]) {
            ull msk = basisB.query_mask(c[j]);
            for (int k = 0; k &lt; m; ++k)
                if (msk &gt;&gt; k & 1) edges.push_back({j, B[k]}); // x_j &lt;= x_{B[k]}
        }
    }

    vector&lt;long long&gt; ans(n);
    vector&lt;int&gt; V_all(n), local_id(n);
    iota(V_all.begin(), V_all.end(), 0);

    auto solve = [&](auto& self, vector&lt;int&gt;& V, vector&lt;pair&lt;int, int&gt;&gt;& E, long long L, long long R) -&gt; void {
        if (V.empty()) return;
        if (L == R) {
            for (int u : V) ans[u] = L;
            return;
        }
        long long M = L + (R - L) / 2;
        int k = V.size();
        for (int i = 0; i &lt; k; ++i) local_id[V[i]] = i;
        int S = k, T = k + 1;
        Dinic dinic(k + 2, S, T);
        for (int i = 0; i &lt; k; ++i) {
            int u = V[i];
            long long delta = 2LL * (v[u] - M) - 1;
            if (delta &gt; 0) dinic.add_edge(S, i, delta);
            else dinic.add_edge(i, T, -delta);
        }
        for (auto [u, w] : E)
            dinic.add_edge(local_id[u], local_id[w], INF);
        dinic.max_flow();

        vector&lt;int&gt; VL, VR;
        for (int i = 0; i &lt; k; ++i) {
            if (dinic.level[i] != -1) VR.push_back(V[i]);
            else VL.push_back(V[i]);
        }
        vector&lt;pair&lt;int, int&gt;&gt; EL, ER;
        for (auto [u, w] : E) {
            bool uR = (dinic.level[local_id[u]] != -1);
            bool wR = (dinic.level[local_id[w]] != -1);
            if (!uR && !wR) EL.push_back({u, w});
            else if (uR && wR) ER.push_back({u, w});
        }
        self(self, VL, EL, L, M);
        self(self, VR, ER, M + 1, R);
    };

    solve(solve, V_all, edges, 0, 1000000);
    unsigned long long total = 0;
    for (int i = 0; i &lt; n; ++i) {
        long long diff = ans[i] - v[i];
        total += (unsigned long long)(diff * diff);
    }
    cout &lt;&lt; total &lt;&lt; "\n";
    return 0;
}







Problem #189 (I3 — Intermediate 3): [Hello 2020 / CF 1284G] Seollal & [LOJ #6515] Greedy Submodular Closure

Judge URLs: https://codeforces.com/problemset/problem/1284/G (Graphic \(\cap\) Partition Matroid Intersection) | https://loj.ac/p/6515 (Parametric / Offline Closure Cut)
Constraints (CF 1284G): \(T \le 20\), \(N, M \le 20\) grid of 'O' and 'X' cells, \(\sum NM \le 400\). Time Limit: \(2.0\text{ s}\).


4-Step Compilation Scratchpad (CF 1284G Seollal)

Step 1 (Diagnostic Signal): We must select a spanning tree of 'O' cells in an \(N \times M\) grid such that every black 'O' cell \(u \in B = \{(r, c) : (r+c) \equiv 0 \pmod 2 \land (r,c) \ne (0,0)\}\) has degree \(\ge 2\) in the tree (AL-18).
Step 2 (Complement / Dualization to Upper Degree Bounds): Wait — a Partition Matroid enforces upper bounds \(|I \cap \delta(u)| \le c_u\), whereas the problem asks for lower bounds \(\deg_T(u) \ge 2\)! How do we flip \(\ge 2\) into \(\le 2\)? Suppose we first look for a forest \(I \subseteq E\) of size \(2|B|\) such that every \(u \in B\) has \(|I \cap \delta(u)| \le 2\). If we find such a forest \(I\) of size \(2|B|\), then because \(\sum_{u \in B} |I \cap \delta(u)| = |I| = 2|B|\) (every grid edge touches at most one vertex in \(B\), since \((0,0)\) is excluded and \(B\) is one side of the bipartite grid!), every \(u \in B\) must have \(|I \cap \delta(u)| = 2\) with equality! Then, because the Graphic Matroid is a matroid, we can greedily add edges from \(E \setminus I\) to extend the forest \(I\) to a full spanning tree \(T \supseteq I\), and adding edges can only increase degrees (\(\deg_T(u) \ge \deg_I(u) = 2\))!
Step 3 (Matroid Intersection Compilation):

Ground set \(E_{\text{good}}\): all grid edges between adjacent 'O' cells, excluding edges incident to \((0, 0)\) when checking \(\mathcal{M}_2\) (or simply define \(B\) as all 'O' cells with \((r+c)\) even and \((r,c) \ne (0,0)\), and only include in \(E\) edges incident to some \(u \in B\); actually any grid edge between 'O' cells not incident to \((0,0)\) touches exactly one cell in \(B\)).
\(\mathcal{M}_1\) (Graphic Matroid): \(I \subseteq E\) is acyclic in the grid graph of 'O' cells.
\(\mathcal{M}_2\) (Partition Matroid): For each \(u \in B\), \(|I \cap \delta(u)| \le 2\).
Run unweighted Matroid Intersection (Algorithm 24.1 via BFS shortest hop-count augmenting paths). Check if \(|I| = 2|B|\) and if the full 'O' graph is connected; if so, greedily extend \(I\) to a spanning tree of all 'O' cells via DSU.

Step 4 (Broken-Gadget Audit FM-25): In G(I), always find the shortest augmenting path from \(X_1\) to \(X_2\) via BFS so that no shortcut chords exist!







Note3-Tier Progressive Hints for #189 ([CF 1284G] Seollal)






Tier 1 (Flipping \(\ge 2\) into \(\le 2\)): Every grid edge not incident to \((0,0)\) is incident to at most one cell in \(B = \{(r,c) : \text{grid}[r][c] == \text{'O'}, (r+c) \equiv 0 \pmod 2, (r,c) \ne (0,0)\}\). If we find an acyclic edge set \(I\) of size \(2|B|\) where each \(u \in B\) has degree \(\le 2\), what must the degree of every \(u \in B\) be?
Tier 2 (Building the Exchange Digraph \(G(I)\)): For \(x \in I\) and \(y \notin I\), \((x \to y) \in A_1\) iff adding \(y\) to the forest \(I\) creates a cycle containing \(x\) (or \(I \setminus \{x\} \cup \{y\}\) is acyclic). And \((y \to x) \in A_2\) iff \(x\) and \(y\) share the same black endpoint \(u \in B\) whose degree in \(I\) is currently \(2\).
Tier 3 (Completing the Spanning Tree): Once \(|I| = 2|B|\), iterate over all remaining grid edges between 'O' cells (including those incident to \((0,0)\)) and add any edge that connects two different DSU components of \(I\). If all 'O' cells end up in one component, print the grid!










TipComplete C++17 Solution for #189 ([Hello 2020 / CF 1284G] Seollal)





#include &lt;bits/stdc++.h&gt;
using namespace std;

struct DSU {
    vector&lt;int&gt; p;
    DSU(int n) : p(n) { iota(p.begin(), p.end(), 0); }
    int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        p[a] = b; return true;
    }
};

struct Edge { int u, v, b_node, r1, c1, r2, c2; };

void solve() {
    int n, m;
    cin &gt;&gt; n &gt;&gt; m;
    vector&lt;string&gt; s(n);
    for (int i = 0; i &lt; n; ++i) cin &gt;&gt; s[i];

    int num_B = 0, total_O = 0;
    vector&lt;vector&lt;int&gt;&gt; b_id(n, vector&lt;int&gt;(m, -1));
    for (int r = 0; r &lt; n; ++r) {
        for (int c = 0; c &lt; m; ++c) {
            if (s[r][c] == 'O') {
                total_O++;
                if ((r + c) % 2 == 0 && (r != 0 || c != 0))
                    b_id[r][c] = num_B++;
            }
        }
    }

    vector&lt;Edge&gt; edges, all_edges;
    for (int r = 0; r &lt; n; ++r) {
        for (int c = 0; c &lt; m; ++c) {
            if (s[r][c] != 'O') continue;
            if (r + 1 &lt; n && s[r + 1][c] == 'O') {
                int bn = (b_id[r][c] != -1) ? b_id[r][c] : b_id[r + 1][c];
                Edge e = {r * m + c, (r + 1) * m + c, bn, r, c, r + 1, c};
                all_edges.push_back(e);
                if (bn != -1) edges.push_back(e);
            }
            if (c + 1 &lt; m && s[r][c + 1] == 'O') {
                int bn = (b_id[r][c] != -1) ? b_id[r][c] : b_id[r][c + 1];
                Edge e = {r * m + c, r * m + c + 1, bn, r, c, r, c + 1};
                all_edges.push_back(e);
                if (bn != -1) edges.push_back(e);
            }
        }
    }

    int E = edges.size();
    vector&lt;int&gt; in_I(E, 0);
    while (true) {
        vector&lt;int&gt; deg(num_B, 0);
        DSU dsu_full(n * m);
        for (int i = 0; i &lt; E; ++i) {
            if (in_I[i]) {
                deg[edges[i].b_node]++;
                dsu_full.unite(edges[i].u, edges[i].v);
            }
        }
        vector&lt;int&gt; X1(E, 0), X2(E, 0);
        queue&lt;int&gt; q;
        vector&lt;int&gt; dist(E, -1), par(E, -1);
        for (int y = 0; y &lt; E; ++y) {
            if (in_I[y]) continue;
            if (dsu_full.find(edges[y].u) != dsu_full.find(edges[y].v)) X1[y] = 1;
            if (deg[edges[y].b_node] &lt; 2) X2[y] = 1;
            if (X1[y]) { dist[y] = 0; q.push(y); }
        }

        // Precompute Graphic exchange: for each x in I, DSU without x
        vector&lt;vector&lt;int&gt;&gt; adj(E);
        for (int x = 0; x &lt; E; ++x) {
            if (!in_I[x]) continue;
            DSU dsu_no_x(n * m);
            for (int i = 0; i &lt; E; ++i)
                if (in_I[i] && i != x) dsu_no_x.unite(edges[i].u, edges[i].v);
            for (int y = 0; y &lt; E; ++y) {
                if (in_I[y]) continue;
                // A1: x -&gt; y if I \ {x} U {y} is acyclic
                if (dsu_no_x.find(edges[y].u) != dsu_no_x.find(edges[y].v))
                    adj[x].push_back(y);
                // A2: y -&gt; x if I \ {x} U {y} satisfies deg &lt;= 2
                if (deg[edges[y].b_node] &lt; 2 || edges[x].b_node == edges[y].b_node)
                    adj[y].push_back(x);
            }
        }

        int target = -1;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (X2[u]) { target = u; break; }
            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    par[v] = u;
                    q.push(v);
                }
            }
        }
        if (target == -1) break;
        for (int cur = target; cur != -1; cur = par[cur]) in_I[cur] ^= 1;
    }

    int cnt_I = accumulate(in_I.begin(), in_I.end(), 0);
    if (cnt_I &lt; 2 * num_B) { cout &lt;&lt; "NO\n"; return; }

    DSU dsu_final(n * m);
    vector&lt;Edge&gt; chosen;
    for (int i = 0; i &lt; E; ++i) {
        if (in_I[i]) {
            dsu_final.unite(edges[i].u, edges[i].v);
            chosen.push_back(edges[i]);
        }
    }
    for (auto& e : all_edges) {
        if (dsu_final.unite(e.u, e.v)) chosen.push_back(e);
    }
    if ((int)chosen.size() != total_O - 1) { cout &lt;&lt; "NO\n"; return; }

    cout &lt;&lt; "YES\n";
    vector&lt;string&gt; out(2 * n - 1, string(2 * m - 1, ' '));
    for (int r = 0; r &lt; n; ++r)
        for (int c = 0; c &lt; m; ++c)
            out[2 * r][2 * c] = s[r][c];
    for (auto& e : chosen)
        out[e.r1 + e.r2][e.c1 + e.c2] = 'O';
    for (auto& row : out) cout &lt;&lt; row &lt;&lt; "\n";
}

