TipComplete C++17 Template for #192 (General \(L_p\) Isotonic Regression Solver)





#include &lt;bits/stdc++.h&gt;
using namespace std;

const double INF = 1e18;
const double EPS = 1e-9;

struct DinicDouble {
    struct Edge { int to, rev; double cap; };
    int n, s, t;
    vector&lt;vector&lt;Edge&gt;&gt; adj;
    vector&lt;int&gt; level, ptr;
    DinicDouble(int n, int s, int t) : n(n), s(s), t(t), adj(n), level(n), ptr(n) {}
    void add_edge(int u, int v, double cap) {
        adj[u].push_back({v, (int)adj[v].size(), cap});
        adj[v].push_back({u, (int)adj[u].size() - 1, 0.0});
    }
    bool bfs() {
        fill(level.begin(), level.end(), -1);
        level[s] = 0;
        queue&lt;int&gt; q; q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& e : adj[u])
                if (e.cap &gt; EPS && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
        }
        return level[t] != -1;
    }
    double dfs(int u, double pushed) {
        if (pushed &lt;= EPS || u == t) return pushed;
        for (int& cid = ptr[u]; cid &lt; (int)adj[u].size(); ++cid) {
            auto& e = adj[u][cid];
            if (level[u] + 1 != level[e.to] || e.cap &lt;= EPS) continue;
            double tr = dfs(e.to, min(pushed, e.cap));
            if (tr &lt;= EPS) continue;
            e.cap -= tr; adj[e.to][e.rev].cap += tr;
            return tr;
        }
        level[u] = -1;
        return 0.0;
    }
    double max_flow() {
        double f = 0;
        while (bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while (double p = dfs(s, INF)) f += p;
        }
        return f;
    }
};

// Solves continuous L_p Isotonic Regression: min sum w_i |x_i - y_i|^p s.t. x_u &lt;= x_v
vector&lt;double&gt; solve_lp_isotonic(int n, double p, const vector&lt;double&gt;& y, const vector&lt;double&gt;& w,
                                 const vector&lt;pair&lt;int, int&gt;&gt;& poset_edges, double L, double R) {
    vector&lt;double&gt; ans(n, 0.0);
    vector&lt;int&gt; V_all(n), local_id(n);
    iota(V_all.begin(), V_all.end(), 0);

    auto rec = [&](auto& self, vector&lt;int&gt;& V, vector&lt;pair&lt;int, int&gt;&gt;& E, double lo, double hi, int depth) -&gt; void {
        if (V.empty()) return;
        if (depth &gt;= 50 || hi - lo &lt; 1e-9) {
            double mid = 0.5 * (lo + hi);
            for (int u : V) ans[u] = mid;
            return;
        }
        double mid = 0.5 * (lo + hi);
        int k = V.size();
        for (int i = 0; i &lt; k; ++i) local_id[V[i]] = i;
        int S = k, T = k + 1;
        DinicDouble dinic(k + 2, S, T);
        for (int i = 0; i &lt; k; ++i) {
            int u = V[i];
            double diff = y[u] - mid;
            double delta = (diff &gt;= 0 ? 1.0 : -1.0) * w[u] * pow(fabs(diff), p - 1.0);
            if (delta &gt; 0) dinic.add_edge(S, i, delta);
            else dinic.add_edge(i, T, -delta);
        }
        for (auto [u, v] : E)
            dinic.add_edge(local_id[u], local_id[v], INF);
        dinic.max_flow();

        vector&lt;int&gt; VL, VR;
        for (int i = 0; i &lt; k; ++i) {
            if (dinic.level[i] != -1) VR.push_back(V[i]);
            else VL.push_back(V[i]);
        }
        vector&lt;pair&lt;int, int&gt;&gt; EL, ER;
        for (auto [u, v] : E) {
            bool uR = (dinic.level[local_id[u]] != -1);
            bool vR = (dinic.level[local_id[v]] != -1);
            if (!uR && !vR) EL.push_back({u, v});
            else if (uR && vR) ER.push_back({u, v});
        }
        self(self, VL, EL, lo, mid, depth + 1);
        self(self, VR, ER, mid, hi, depth + 1);
    };

    rec(rec, V_all, poset_edges, L, R, 0);
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m; double p;
    if (!(cin &gt;&gt; n &gt;&gt; m &gt;&gt; p)) return 0;
    vector&lt;double&gt; y(n), w(n);
    double L = 1e18, R = -1e18;
    for (int i = 0; i &lt; n; ++i) { cin &gt;&gt; y[i]; L = min(L, y[i]); R = max(R, y[i]); }
    for (int i = 0; i &lt; n; ++i) cin &gt;&gt; w[i];
    vector&lt;pair&lt;int, int&gt;&gt; edges(m);
    for (int i = 0; i &lt; m; ++i) { cin &gt;&gt; edges[i].first &gt;&gt; edges[i].second; --edges[i].first; --edges[i].second; }

    auto x = solve_lp_isotonic(n, p, y, w, edges, L, R);
    double total = 0;
    for (int i = 0; i &lt; n; ++i) total += w[i] * pow(fabs(x[i] - y[i]), p);
    cout &lt;&lt; fixed &lt;&lt; setprecision(6) &lt;&lt; total &lt;&lt; "\n";
    return 0;
}

Rings, Valuations, and Formal Laurent Residues

Formal Power Series Ring \(K[[x]]\): For a commutative ring \(K\) with unity, \(K[[x]]\) is the ring of infinite formal series \(F(x) = \sum_{n=0}^{\infty} f_n x^n\) equipped with Cauchy convolution \([x^n](F \cdot G) = \sum_{i+j=n} f_i g_j\).
\(x\)-Adic Valuation \(\nu(F) = \operatorname{val}(F) = \operatorname{ord}_x(F)\): The valuation (or order, also written \(\operatorname{val}_x(F)\) or \(\operatorname{ord}_x(F)\)) of \(F(x) \in K((x))\) is the lowest index of a non-zero coefficient: \[\nu(F) = \operatorname{val}(F) = \operatorname{ord}_x(F) = \min\{n \in \mathbb{Z} : [x^n]F(x) \neq 0\}, \qquad \nu(0) = +\infty.\] An infinite sum \(\sum_{k \ge 0} F_k(x)\) or infinite product \(\prod_{k \ge 1}(1 + G_k(x))\) converges in the \(x\)-adic topology if and only if \(\lim_{k \to \infty} \nu(F_k) = +\infty\) (respectively \(\lim_{k \to \infty} \nu(G_k) = +\infty\)).
Unit Criterion in \(K[[x]]^\times\): \(F(x) \in K[[x]]\) has a multiplicative inverse \(F(x)^{-1} \in K[[x]]\) if and only if its constant term is a unit in \(K\): \([x^0]F(x) \in K^\times\).
Formal Laurent Series Ring \(K((x))\): \(K((x)) = K[[x]][x^{-1}]\) consists of formal series \(A(x) = \sum_{n=v}^{\infty} a_n x^n\) with finite lower bound \(v \in \mathbb{Z}\) (at most finitely many negative powers of \(x\)). When \(K\) is a field, \(K((x))\) is the fraction field of \(K[[x]]\).
Formal Residue Operator \(\operatorname{Res}_{x=0} = \operatorname{Res}_x\): For \(F(x) \in K((x))\), the formal residue is purely algebraic: \[\operatorname{Res}_{x=0} F(x) = \operatorname{Res}_x F(x) = \operatorname{Res}_{x=0} F(x)\,dx = [x^{-1}]F(x).\] It satisfies \(\operatorname{Res}_{x=0} A'(x) = 0\) for all \(A(x) \in K((x))\) in every characteristic, and Jacobi’s Formal Change-of-Variables Formula for any \(G(u) \in K[[u]]\) with \(\nu(G) = 1\) and \([u^1]G(u) \in K^\times\): \[\operatorname{Res}_{x=0} F(x)\,dx = \operatorname{Res}_{u=0} F(G(u))\,G'(u)\,du.\]
5-Ring Bivariate Hierarchy (Ch 15–Ch 17):

\(K[y][[x]]\) — polynomials in \(y\) over \(x\)-power series (\(\deg_y f_n(y) &lt; \infty\) for each \(n\));
\((K[y, y^{-1}])[[x]]\) — Laurent polynomials in \(y\) at each power of \(x\) (the natural ring for 1D lattice walk step polynomials, where substituting a small root \(y = y_0(x)\) with \(\nu_x(y_0) \ge 1\) converges in the \(x\)-adic topology);
\(K[[x, y]]\) — formal power series in two commuting variables (supporting arbitrary \((n, m) \in \mathbb{Z}_{\ge 0}^2\));
\(K((x))[[y]]\) — formal power series in \(y\) over the Laurent field \(K((x))\) (bounded below in \(x\) for each fixed \(y^m\); note that \(K((x))[[y]]\) and \(K((y))[[x]]\) are not isomorphic: \(\frac{1}{x - y} = \sum_{k \ge 0} x^{-k-1} y^k \in K((x))[[y]]\) vs. \(-\sum_{k \ge 0} x^k y^{-k-1} \in K((y))[[x]]\));
\(K((z))[[t]]\) — formal power series in \(t\) over the Laurent field \(K((z))\) (the Furstenberg Diagonal Ring, where \(x = z, \, y = t z^{-1}\) converts \([x^n y^n]F(x, y)\) into the 1D residue \([t^n]\operatorname{Res}_{z=0}\bigl(z^{-1}F(z, t z^{-1})\bigr)\) because each fixed power \(t^k\) has Laurent \(z\)-valuation bounded below by \(-k\)).

Prerequisites and learning objectives
You need arithmetic with integers and fractions, and nothing else. The notation reference collects conventions used throughout the book.
By the end of this chapter you should be able to:

read a quantified statement (“for every … there exists …”) and say precisely what a counterexample to it would look like;
pick a proof technique — direct, contrapositive, contradiction, induction — for a claim, and know why each one is valid;
state an invariant for a process and use it to prove that a target state is unreachable, or a potential function to prove that a loop ends;
derive Bézout’s identity from Euclid’s algorithm and use it to decide when \(ax + by = c\) has integer solutions and what all of them are;
justify a counting formula by exhibiting a bijection or by counting one set in two ways.

If all of this is familiar, skim the section headings and jump to the exercises; they are designed to locate gaps rather than to gatekeep.

Suppose you must count the pairs \((x,y)\) with \(1 \le x, y \le 10^7\) and \(\gcd(x,y) = 1\). Iterating over pairs is \(10^{14}\) operations. Iterating over gcd values is \(10^7\). Same problem, different index, seven orders of magnitude.
That is the whole subject of this chapter. Nothing here is about numbers being mysterious; everything is about re-indexing a sum so the work collapses:

from integers to their prime powers, because most quantities of interest are determined independently at each prime;
from pairs to their gcd, turning an exact condition into a weighted sum over divisors;
from all \(n\) values of \(\lfloor n/i \rfloor\) to the \(O(\sqrt n)\) distinct ones, because the quotient is constant on long stretches.

Learn the three re-indexings and the formulas write themselves. Memorize the formulas instead and you will be stuck the moment a problem perturbs them.

